+  const perf = rehearsal.performance_readability ?? {};
+  const oversized = requiredNumber(
+    perf.oversized_image_asset_count,
+    'oversized_image_asset_count_not_finite_number',
+    blockers,
+  );
+  const mobileFails = requiredNumber(
+    perf.mobile_readability_fail_count,
+    'mobile_readability_fail_count_not_finite_number',
+    blockers,
