+  if (mobileFails !== null && mobileFails !== 0) blockers.push('mobile_readability_fail_count_not_zero');
+  if (perf.page_label_component_context_visible !== true) {
+    blockers.push('page_label_component_context_not_visible');
+  }
+  if (perf.same_page_neighbor_warning_visible_without_covering_source !== true) {
+    blockers.push('same_page_neighbor_warning_not_visible_without_covering_source');
+  }
+  if (perf.fallback_states_readable_mobile_and_desktop !== true) {
+    blockers.push('fallback_states_not_readable_mobile_and_desktop');
+  }
+  return oversized === 0 &&
+    mobileFails === 0 &&
+    latency !== null &&
+    perf.page_label_component_context_visible === true &&
+    perf.same_page_neighbor_warning_visible_without_covering_source === true &&
+    perf.fallback_states_readable_mobile_and_desktop === true;
+}
+
+export function validatePostAttemptMsRevealLaunchRehearsal(options = {}) {
+  const rehearsal = isRecord(options) ? options.rehearsal : null;
+  if (!isRecord(rehearsal)) return failResult(['rehearsal_required']);
+  const blockers = [];
+
+  const sourceArtifacts = asArray(rehearsal.source_artifacts).filter(isRecord);
+  const sourceRoles = new Set(sourceArtifacts.map((artifact) => artifact.role));
+  const sourceRolesPresent = SOURCE_INPUTS.every(([role]) => sourceRoles.has(role));
+  if (!sourceRolesPresent) blockers.push('source_artifacts_missing_expected_roles');
+  const sourceArtifactGateFailures = sourceArtifactFailures(sourceArtifacts);
+  for (const failure of sourceArtifactGateFailures) {
+    blockers.push(failure);
+  }
+  if (rehearsal.source_artifact_gate?.status === 'fail') {
+    for (const failure of asArray(rehearsal.source_artifact_gate.failures)) {
+      blockers.push(failure);
+    }
+  }
+  const sourceArtifactsValid =
+    sourceRolesPresent &&
+    sourceArtifactGateFailures.length === 0 &&
+    rehearsal.source_artifact_gate?.status !== 'fail';
+
+  const sequentialDependencyValid =
+    rehearsal.sequential_dependency?.issue === 1496 &&
+    rehearsal.sequential_dependency?.merged_to_main === true &&
+    rehearsal.sequential_dependency?.runtime_rehearsal_artifacts_present === true &&
+    rehearsal.sequential_dependency?.runtime_rehearsal_validator_status === 'pass' &&
+    sourceArtifactsValid;

