+  const root = typeof options.root === 'string' ? options.root : repoRootFromScript();
+  const paths = pathsFromOptions(options);
+  const generatedAt = options.generatedAt ?? GENERATED_AT;
+  const inputs = loadInputs(root, paths);
+  const rehearsal = buildRehearsal({ root, paths, generatedAt, inputs });
+  if (!sourceArtifactsPass(inputs.sourceArtifacts, inputs.payloads)) {
